namespace App\Notifications;

use Illuminate\Bus\Queueable;
use Illuminate\Notifications\Notification;

/**
 * Scheduler reminder notification (Fixzy SysMaker Scheduler module).
 * Delivered to the database channel (live bell when the realtime module
 * is on) and by mail when the user has an address.
 */
class SchedulerReminder extends Notification
{
    use Queueable;

    /**
     * Build the scheduler reminder payload.
     *
     * @param  string  $title  Reminder title.
     * @param  string  $body  Reminder body text.
     */
    public function __construct(
        public string $title,
        public string $body,
    ) {}

    /**
     * Delivery channels: database always, mail when the user has an address.
     *
     * @param  mixed  $notifiable  Notifiable model.
     * @return  array  Channel names.
     */
    public function via($notifiable): array
    {
        $channels = ['database'];
        if (! empty($notifiable->email)) {
            $channels[] = 'mail';
        }

        return $channels;
    }

    /**
     * Mail representation of the reminder.
     *
     * @param  mixed  $notifiable  Notifiable model.
     * @return  \Illuminate\Notifications\Messages\MailMessage  The mail message.
     */
    public function toMail($notifiable): \Illuminate\Notifications\Messages\MailMessage
    {
        return (new \Illuminate\Notifications\Messages\MailMessage)
            ->subject($this->title)
            ->line($this->title)
            ->line($this->body);
    }

    /**
     * Database-channel payload for the live notification bell.
     *
     * @param  mixed  $notifiable  Notifiable model.
     * @return  array  Notification payload.
     */
    public function toArray($notifiable): array
    {
        return [
            'title' => $this->title,
            'body' => $this->body,
            'icon' => 'heroicon-o-bell-alert',
            'iconColor' => 'warning',
        ];
    }
}
